create table public.forecast_performance_snapshots(id uuid primary key default gen_random_uuid(),snapshot_key text not null unique,performance_version text not null,calibration_version text not null,forecast_method text not null,model_version text not null,horizon text not null,data_quality_bucket text not null,information_cutoff_at timestamptz not null,available_at timestamptz not null,status text not null check(status in('AVAILABLE','INSUFFICIENT_DATA')),reason text,sample_size integer not null,probability_sample_size integer not null,metrics jsonb not null,input_hash text not null,created_at timestamptz not null default now());
create table public.forecast_calibration_buckets(id uuid primary key default gen_random_uuid(),snapshot_id uuid not null references public.forecast_performance_snapshots(id),bucket_lower numeric not null,bucket_upper numeric not null,sample_size integer not null,status text not null check(status in('VALUE','INSUFFICIENT_DATA')),mean_predicted numeric,observed_rate numeric,absolute_gap numeric,bucket_hash text not null unique,created_at timestamptz not null default now(),unique(snapshot_id,bucket_lower,bucket_upper));
create or replace function public.prevent_forecast_performance_mutation()returns trigger language plpgsql as $$begin raise exception'Forecast performance history is immutable';end$$;create trigger forecast_performance_snapshots_immutable before update or delete on public.forecast_performance_snapshots for each row execute function public.prevent_forecast_performance_mutation();create trigger forecast_calibration_buckets_immutable before update or delete on public.forecast_calibration_buckets for each row execute function public.prevent_forecast_performance_mutation();
alter table public.forecast_performance_snapshots enable row level security;alter table public.forecast_calibration_buckets enable row level security;create policy "public read forecast performance" on public.forecast_performance_snapshots for select using(true);create policy "public read forecast calibration" on public.forecast_calibration_buckets for select using(true);grant select on public.forecast_performance_snapshots,public.forecast_calibration_buckets to anon,authenticated;grant all on public.forecast_performance_snapshots,public.forecast_calibration_buckets to service_role;
alter table public.ingestion_runs drop constraint if exists ingestion_runs_job_kind_check;alter table public.ingestion_runs add constraint ingestion_runs_job_kind_check check(job_kind in('stock_quotes','wallet_transactions','wallet_discovery','crypto_market','wallet_pnl','wallet_evidence','fast_flow','wallet_clustering','jackpot_collector','jackpot_outcomes','market_events','paper_eligibility','paper_execution','paper_exits','paper_valuation','performance','fx','qualification','data_gap_closure','simulation','historical_replay','forecast_catalyst','expert_knowledge','baseline_forecast','forecast_performance'));
